export const DS_ICON_CSS = "\n/* Zenya animated icons */\n.zi{display:inline-flex;line-height:0}\n.zi svg{width:1em;height:1em;overflow:visible}\n.ds-ico svg{width:100%;height:100%}\n.zi svg *{transform-box:view-box;transform-origin:12px 12px}\n@keyframes zi-swing{0%,100%{transform:rotate(0)}18%{transform:rotate(-13deg)}38%{transform:rotate(10deg)}56%{transform:rotate(-8deg)}72%{transform:rotate(6deg)}86%{transform:rotate(-3deg)}}\n@keyframes zi-spin{to{transform:rotate(360deg)}}\n@keyframes zi-flip{to{transform:rotate(180deg)}}\n@keyframes zi-beat{0%,100%{transform:scale(1)}25%{transform:scale(1.18)}45%{transform:scale(.94)}70%{transform:scale(1.12)}}\n@keyframes zi-pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.12)}}\n@keyframes zi-pop{0%,100%{transform:scale(1)}45%{transform:scale(1.22)}}\n@keyframes zi-popspin{0%,100%{transform:rotate(0) scale(1)}50%{transform:rotate(72deg) scale(1.2)}}\n@keyframes zi-tilt{0%,100%{transform:rotate(0)}35%{transform:rotate(-7deg)}70%{transform:rotate(5deg)}}\n@keyframes zi-sway{0%,100%{transform:rotate(0)}25%{transform:rotate(-8deg)}55%{transform:rotate(6deg)}80%{transform:rotate(-4deg)}}\n@keyframes zi-wobble{0%,100%{transform:rotate(0)}20%{transform:rotate(-6deg) scale(1.05)}60%{transform:rotate(5deg)}}\n@keyframes zi-shake{0%,100%{transform:rotate(0)}20%{transform:rotate(-11deg)}40%{transform:rotate(9deg)}60%{transform:rotate(-7deg)}80%{transform:rotate(5deg)}}\n@keyframes zi-wiggle{0%,100%{transform:translate(0,0)}25%{transform:translate(-2px,2px)}55%{transform:translate(2px,-1px)}80%{transform:translate(-1px,1px)}}\n@keyframes zi-nudge{0%,100%{transform:translateX(0)}30%{transform:translateX(-1.5px)}65%{transform:translateX(2px)}}\n@keyframes zi-slide{0%,100%{transform:translateX(0)}50%{transform:translateX(3.5px)}}\n@keyframes zi-fly{0%,100%{transform:translate(0,0)}50%{transform:translate(3px,-3px)}}\n@keyframes zi-jump{0%,100%{transform:translateY(0)}40%{transform:translateY(-3px)}70%{transform:translateY(1px)}}\n@keyframes zi-bob{0%,100%{transform:translateY(0)}50%{transform:translateY(-2px)}}\n@keyframes zi-wave{0%,100%{transform:rotate(0)}25%{transform:rotate(6deg)}75%{transform:rotate(-6deg)}}\n@keyframes zi-flash{0%,100%{transform:scale(1);opacity:1}40%{transform:scale(1.15);opacity:.5}}\n@keyframes zi-flicker{0%,100%{transform:scale(1) rotate(0);opacity:1}30%{transform:scale(1.08) rotate(-4deg);opacity:.75}60%{transform:scale(.96) rotate(3deg);opacity:1}}\n@keyframes zi-lift{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-1.5px) scale(1.22)}}\n@keyframes zi-twinkle{0%{transform:scale(.6);opacity:.4}60%{transform:scale(1.3);opacity:1}100%{transform:scale(1);opacity:1}}\n@keyframes zi-draw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}\n.zi-draw{stroke-dasharray:1;stroke-dashoffset:0}\n.zi:hover .zi-swing,[class$=\"__item\"]:hover .zi-swing,[class$=\"__card\"]:hover .zi-swing{animation:zi-swing .9s ease-in-out}\n.zi:hover .zi-spin,[class$=\"__item\"]:hover .zi-spin,[class$=\"__card\"]:hover .zi-spin{animation:zi-spin .7s cubic-bezier(.4,0,.2,1)}\n.zi:hover .zi-flip{animation:zi-flip .6s cubic-bezier(.4,0,.2,1)}\n.zi:hover .zi-beat,[class$=\"__item\"]:hover .zi-beat,[class$=\"__card\"]:hover .zi-beat{animation:zi-beat .7s ease-in-out}\n.zi:hover .zi-pulse{animation:zi-pulse .8s ease-in-out}\n.zi:hover .zi-pop,[class$=\"__item\"]:hover .zi-pop,[class$=\"__card\"]:hover .zi-pop{animation:zi-pop .5s cubic-bezier(.2,1.4,.4,1)}\n.zi:hover .zi-popspin,[class$=\"__item\"]:hover .zi-popspin,[class$=\"__card\"]:hover .zi-popspin{animation:zi-popspin .7s ease-in-out}\n.zi:hover .zi-tilt{animation:zi-tilt .8s ease-in-out}\n.zi:hover .zi-sway{animation:zi-sway 1s ease-in-out}\n.zi:hover .zi-wobble{animation:zi-wobble .7s ease-in-out}\n.zi:hover .zi-shake{animation:zi-shake .8s ease-in-out}\n.zi:hover .zi-wiggle{animation:zi-wiggle .7s ease-in-out}\n.zi:hover .zi-nudge,[class$=\"__item\"]:hover .zi-nudge,[class$=\"__card\"]:hover .zi-nudge{animation:zi-nudge .7s ease-in-out}\n.zi:hover .zi-slide{animation:zi-slide .6s ease-in-out}\n.zi:hover .zi-fly,[class$=\"__item\"]:hover .zi-fly,[class$=\"__card\"]:hover .zi-fly{animation:zi-fly .7s ease-in-out}\n.zi:hover .zi-jump{animation:zi-jump .6s ease-in-out}\n.zi:hover .zi-bob,[class$=\"__item\"]:hover .zi-bob,[class$=\"__card\"]:hover .zi-bob{animation:zi-bob .5s ease-in-out}\n.zi:hover .zi-bob2{animation:zi-bob .5s ease-in-out .08s}\n.zi:hover .zi-wave{animation:zi-wave .7s ease-in-out}\n.zi:hover .zi-flash{animation:zi-flash .6s ease-in-out}\n.zi:hover .zi-flicker{animation:zi-flicker .7s ease-in-out}\n.zi:hover .zi-lift,[class$=\"__item\"]:hover .zi-lift,[class$=\"__card\"]:hover .zi-lift{animation:zi-lift .6s ease-in-out}\n.zi:hover .zi-draw,[class$=\"__item\"]:hover .zi-draw,[class$=\"__card\"]:hover .zi-draw{animation:zi-draw .55s ease-in-out}\n.zi:hover .zi-twinkle,[class$=\"__item\"]:hover .zi-twinkle,[class$=\"__card\"]:hover .zi-twinkle{animation:zi-twinkle .6s ease-in-out}\n.zi:hover .zi-twinkle2{animation:zi-twinkle .6s ease-in-out .1s}\n.zi:hover .zi-twinkle3{animation:zi-twinkle .6s ease-in-out .18s}\n@media (prefers-reduced-motion:reduce){.zi *{animation:none !important}}\n"
